def count_primes(N):
    primes = []
    is_prime = [True] * (N + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, N + 1):
        if is_prime[p]:
            primes.append(p)
            for i in range(p * p, N + 1, p):
                is_prime[i] = False
    return len(primes)

